import{_ as a,o,c as r,j as e}from"./chunks/framework.8tqBsFWt.js";const m=JSON.parse(`{"title":"Not Everyone Works Forty Hours","description":"Capacity planning only works if the system knows how each person actually works. VERA was treating your contractors like full-time employees. It no longer does.","frontmatter":{"title":"Not Everyone Works Forty Hours","date":"2026-03-29","series":"Features","description":"Capacity planning only works if the system knows how each person actually works. VERA was treating your contractors like full-time employees. It no longer does.","sidebar":false,"prev":false,"next":false},"headers":[],"relativePath":"blog/21-not-everyone-works-forty-hours.md","filePath":"blog/21-not-everyone-works-forty-hours.md","blogPosts":[{"url":"/blog/22-getvera-site","fm":{"title":"A Proper Address","date":"2026-04-18","series":"Infrastructure","description":"VERA now lives at getvera.site. The old GitHub Pages URL redirects automatically — but the address a prospect reads on a pricing page is part of the pitch."}},{"url":"/blog/21-not-everyone-works-forty-hours","fm":{"title":"Not Everyone Works Forty Hours","date":"2026-03-29","series":"Features","description":"Capacity planning only works if the system knows how each person actually works. VERA was treating your contractors like full-time employees. It no longer does."}},{"url":"/blog/20-when-done-means-done","fm":{"title":"When Done Means Done","date":"2026-03-25","series":"AI Behaviour","description":"A confirmation that nothing happened behind it is worse than no confirmation at all. We fixed the moment where trust breaks."}},{"url":"/blog/19-the-briefing","fm":{"title":"The Briefing That Replaced the Monday Check-in","date":"2026-03-24","series":"Features","description":"The morning summary now answers two questions simultaneously: what am I supposed to be working on, and where do my projects stand?"}},{"url":"/blog/18-sheets-formulas-as-code","fm":{"title":"Building the Dashboard the Owner Actually Needs","date":"2026-03-15","series":"Data Model","description":"A live dashboard that answers the real questions: which projects are healthy, which are at risk, and what the business earned this month."}},{"url":"/blog/17-two-spreadsheets","fm":{"title":"The Dashboard Is Always Current","date":"2026-03-13","series":"Architecture","description":"The client''s reporting view and the database are separate spreadsheets. The client can never accidentally break the data — and they never have to request a report."}},{"url":"/blog/16-column-order-is-the-api","fm":{"title":"The Invisible Contract in the Spreadsheet","date":"2026-03-12","series":"Data Model","description":"Google Sheets doesn''t enforce its own structure. We had to. The rules we built to keep the data trustworthy."}},{"url":"/blog/14-agile-as-billing-model","fm":{"title":"Agile as a Billing Model","date":"2026-03-08","series":"Business Logic","description":"A sprint is a delivery unit and a revenue recognition unit. Timeliness of logging determines timeliness of revenue — they''re the same thing."}},{"url":"/blog/15-ooo-is-a-financial-event","fm":{"title":"Absence Is Data Too","date":"2026-03-08","series":"Business Logic","description":"Time off is a cost. If it doesn''t appear in the same system as time worked, the capacity picture is wrong and the P&L is incomplete."}},{"url":"/blog/13-design-md-rethink","fm":{"title":"Writing It Down Made Us Confront What We''d Built","date":"2026-03-07","series":"Architecture","description":"Six weeks in, we stopped and wrote down every decision we''d made. Several of them turned out to be wrong."}},{"url":"/blog/12-phased-expansion","fm":{"title":"What Becomes Possible When the Data Is Real","date":"2026-03-03","series":"Features","description":"Once time tracking is accurate and timely, a layer of project intelligence that was previously impossible becomes straightforward."}},{"url":"/blog/11-multi-tenancy-bugs","fm":{"title":"Reliability Is the Promise","date":"2026-03-01","series":"Architecture","description":"Timeliness only works if the system is there when the moment arrives. Getting multi-tenant reliability right was non-negotiable."}},{"url":"/blog/10-multi-tenancy","fm":{"title":"Each Client Gets Their Own VERA","date":"2026-02-25","series":"Architecture","description":"Multi-tenancy wasn''t a feature request. It was the point. A tool that feels shared feels like someone else''s."}},{"url":"/blog/09-timebot-becomes-vera","fm":{"title":"TimeBot Becomes VERA","date":"2026-02-22","series":"Origins","description":"A name signals a relationship. We weren''t building a utility."}},{"url":"/blog/07-retainers-are-weird","fm":{"title":"Retainers Without Timely Data Are Just Guesses","date":"2026-02-19","series":"Business Logic","description":"A retainer is a commitment to deliver a volume of work within a period. If you don''t know where you are until the invoice, you''ve already lost."}},{"url":"/blog/08-snapshots-version-control-spreadsheet","fm":{"title":"The Business Was There Last Tuesday Too","date":"2026-02-19","series":"Infrastructure","description":"When data is live and timely, the next question is whether you can go back. We built that in from the start."}},{"url":"/blog/06-roles-and-dollars","fm":{"title":"The Data Is Only Worth Protecting If It''s Worth Something","date":"2026-02-17","series":"Permissions","description":"When the data is timely and accurate, the financial numbers become real. Real numbers need to reach the right people — and not the wrong ones."}},{"url":"/blog/04-schema-grows-up","fm":{"title":"Making a Slack Message Do the Work of a Form","date":"2026-02-12","series":"Data Model","description":"We removed the interface. That meant every piece of information the owner needed had to be captured from a casual Slack message without making that message any harder to send."}},{"url":"/blog/05-prompt-engineering-wars","fm":{"title":"The Clarifying Questions Problem","date":"2026-02-12","series":"AI Behaviour","description":"Timeliness is the whole product. Any friction that risks the timing is a product failure."}},{"url":"/blog/03-socket-mode-railway","fm":{"title":"The Deployment That Didn''t Require a Web App","date":"2026-02-11","series":"Infrastructure","description":"We needed to deploy without adding anything to the client''s stack. Socket Mode and Railway made that possible for almost nothing."}},{"url":"/blog/01-the-problem","fm":{"title":"The Problem That Made VERA Necessary","date":"2026-02-10","series":"Origins","description":"Every time tracking tool ever built starts from the wrong assumption. We found the one thing that fixes it."}},{"url":"/blog/02-day-one-slack-claude-sheets","fm":{"title":"Day One: Slack → Claude → Google Sheets","date":"2026-02-10","series":"Origins","description":"The three components we chose on day one — and why each one was chosen specifically because it required no new interface."}}]}`),s={name:"blog/21-not-everyone-works-forty-hours.md"};function i(n,t,l,h,d,c){return o(),r("div",null,[...t[0]||(t[0]=[e("p",null,"Every agency has the same team structure. A core of full-time people, a layer of contractors who come in for specific projects or specific skills, and occasionally a vendor handling a defined piece of work. Most time tracking tools treat all of them the same way. That's the problem.",-1),e("p",null,"When we built capacity tracking into VERA, we made the same mistake. A contractor working three days a week was being evaluated against a forty-hour week. They appeared perpetually overbooked — not because they were, but because the system was measuring them against a standard they'd never agreed to. The overbooking warning fired, and you ignored it, because it was always wrong.",-1),e("p",null,"A warning you learn to ignore is worse than no warning at all.",-1),e("p",null,"The fix was to make hours-per-week a property of the person, not the team. When you add a contractor to VERA now, it asks how many hours a week they work before creating the record. A three-day contractor at standard hours: twenty-four. A part-time senior designer doing two days a week: sixteen. VERA stores that number against the user and uses it for every capacity calculation that involves them. Full-time employees default to forty without prompting. Vendors use forty as a placeholder, since their cost is governed by agreed fixed payments rather than tracked time.",-1),e("p",null,"The derived number — hours per day — follows proportionally. A contractor at twenty-four hours across a five-day week is available for 4.8 hours on any given working day. That changes how their envelopes are evaluated, how their headroom is reported in the morning briefing, and how the overbooking check fires when you try to add new work.",-1),e("p",null,"There was a second problem hiding underneath the first. Time off — sick days, leave, PTO — is logged as hours in VERA. When a contractor takes a sick day, it was being recorded at eight hours, because that's what a sick day looks like for a full-time employee. But for a contractor whose day is 4.8 hours, subtracting eight hours was consuming more than a day's capacity and making their availability look worse than it was. In edge cases it could push available hours below zero.",-1),e("p",null,"The fix there is a single constraint: no time-off entry can subtract more than the person's actual working day. A sick day logged at eight hours for a 4.8-hour contractor subtracts 4.8. A half-day of PTO logged at four hours passes through unchanged, because it's already within range. The arithmetic now reflects the actual shape of the person's schedule.",-1),e("p",null,"Capacity planning is only useful if the numbers are calibrated to reality. An agency where half the team are contractors was always going to break a system that assumed everyone worked the same hours. The numbers are now specific to each person — which is the only way they're worth looking at.",-1)])])}const g=a(s,[["render",i]]);export{m as __pageData,g as default};
